mapper.sql:
WHERE e.active=TRUE AND c.active=TRUE
AND e.category_id=#{categoryId}
AND e.difficulty=#{difficulty}
AND e.pronunciation_rule=#{rule}
AND e.content_type=#{contentType}

AND (e.title LIKE CONCAT('%',#{keyword},'%')
  OR EXISTS (SELECT 1 FROM exercise_items k WHERE k.exercise_id=e.exercise_id AND k.text_value LIKE CONCAT('%',#{keyword},'%')))

mapper.select:
SELECT 
FROM exercises e JOIN practice_categories c ON c.category_id=e.category_id

ORDER BY c.sort_order,e.sort_order,e.exercise_id LIMIT #{limit} OFFSET #{offset}

SELECT exercise_id AS exerciseId,item_id AS itemId,text_value AS word,text_value AS text,image_url AS imageUrl,emoji
FROM exercise_items WHERE exercise_id IN #{id}
ORDER BY exercise_id,sort_order
